 await f.control('authorize',{authorized:true,policy_sha256:f.store.dispatchBinding.scope.policy_sha256});await f.clock();assert.equal((await f.run()).status,200);const internal=Object.values((await f.app.snapshot()).operations.requests).filter(q=>q.internal_notification===true);assert.ok(internal.length>0);
 let s=await f.app.snapshot(),r=s.prospects.second;for(const [type,data]of [['reply_reviewed',{source_id:r.reply.source_id,reply_sha256:hash(r.reply),outcome:'discovery',focus:'website'}],['reply_draft_saved',{source_id:r.reply.source_id,reply_sha256:hash(r.reply),source_sha256:r.reply.content.source_sha256,body:'A separate current reply on the declared second thread.'}]])await signed(f,type,data,'owner','signed-second-'+type,'second');r=(await f.app.snapshot()).prospects.second;await signed(f,'reply_draft_approved',{sha256:r.reply_draft.sha256,approved:true,facts_checked:true},'owner','signed-second-facts','second');const selector={project_id:'second',kind:'reply'},pkg=await f.call('package',selector),a=await f.call('approve',{...selector,revision:(await f.app.snapshot()).revision,event_id:'signed-second-send',package_sha256:pkg.sha256,approved:true,facts_checked:true});
